+// API keys and roles. Keys live in the data as `apiKeys`.
+
+/** The roles, from least to most powerful. */
+export const ROLES = Object.freeze(["viewer", "cook", "manager"]);
+
+// Changes (non-GET) a cook may also make, by route pattern.
+const COOK_ROUTES = new Set([
+  "POST /recipes/:id/cook",
+  "POST /batches/:id/waste",
+  "POST /temperatures",
+  "POST /stocktakes/:id/counts",
+]);
+
+// Reads only managers may make.
+const MANAGER_READS = new Set(["GET /audit"]);
+
+/** The api key record for a bearer token, or null. */
+export function findKey(store, token) {
+  if (!token) return null;
+  return (store.data.apiKeys ?? []).find((k) => k.key === token) ?? null;
+}
+
+/** Whether `role` may call the route `method pattern`. */
+export function mayCall(role, method, pattern) {
+  const route = `${method} ${pattern}`;
+  if (role === "manager") return true;
+  if (method === "GET") return !MANAGER_READS.has(route);
+  return role === "cook" && COOK_ROUTES.has(route);
+}
