+++ b/tests/auth.test.js
@@ -0,0 +1,37 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { app } from "./helpers.js";
+
+const as = (key) => ({ authorization: `Bearer ${key}` });
+
+test("missing or unknown keys are 401", async () => {
+  const { raw } = app();
+  const a = await raw({ path: "/items" });
+  assert.equal(a.status, 401);
+  assert.equal(a.body.error.code, "unauthorized");
+  assert.equal((await raw({ path: "/items", headers: as("nope") })).status, 401);
+});
+
+test("roles limit what a key may do", async () => {
+  const { raw } = app();
+  assert.equal((await raw({ path: "/items", headers: as("viewer-key") })).status, 200);
+  const v = await raw({ method: "POST", path: "/recipes/1/cook", headers: as("viewer-key"), body: { portions: 1 } });
+  assert.equal(v.status, 403);
+  assert.equal(v.body.error.code, "forbidden");
+  assert.equal((await raw({ method: "POST", path: "/recipes/1/cook", headers: as("cook-key"), body: { portions: 1 } })).status, 200);
+  assert.equal((await raw({ method: "POST", path: "/stocktakes", headers: as("cook-key"), body: { location: "dry" } })).status, 403);
+  assert.equal((await raw({ path: "/audit", headers: as("cook-key") })).status, 403);
+});
+
+test("changes are audited, newest first, for managers", async () => {
+  const { raw } = app();
+  await raw({ method: "POST", path: "/recipes/1/cook", headers: as("cook-key"), body: { portions: 1 } });
+  await raw({ method: "POST", path: "/recipes/1/cook", headers: as("viewer-key"), body: { portions: 1 } });
+  const res = await raw({ path: "/audit", headers: as("manager-key") });
+  assert.equal(res.status, 200);
+  assert.deepEqual(res.body.map((e) => [e.key, e.method, e.path, e.status]), [
+    ["viewer", "POST", "/recipes/1/cook", 403],
+    ["cook", "POST", "/recipes/1/cook", 200],
+  ]);
+  assert.ok(res.body[0].at);
+});
